using HunterDriver=G2NaturalDriver;

int main(int argc,char** argv){try{std::cout.setf(std::ios::unitbuf);need(argc==5,"G2package source isolated-root rules|natural|load");auto c=loadCombatContent(argv[1]);need(c.compatibility=="post-f5-g2-normal-3","G2 hunters not delivered");const std::filesystem::path root=argv[3];std::filesystem::create_directories(root);const std::string source=read(argv[2]);SaveFiles disk(c,root);auto saved=decodeSave(c,source);if(std::string(argv[4])=="rules"){rules(c,saved,source);return 0;}HunterDriver run(c,root,"public-inputs-"+std::string(argv[4])+".jsonl");run.game.configureSaveDirectory(root);
 const std::string mode=argv[4];if(mode!="load"){std::ofstream(root/"slot-01.json")<<source;}run.load(mode=="load"?2:1);
 if(mode=="load"){need(run.game.mapId()==151&&run.game.session().flag(382)&&run.game.session().flag(383)&&run.game.session().flag(446),"G2-03 independent Load lost permanent facts");run.enterLift();run.enterHunters();need(run.alive().empty(),"G2-03 independent Load revived hunters");run.actObject("m162-e13");need(run.game.mapId()==163,"G2-03 independent Load cannot enter163");run.actObject("m163-e3");need(run.game.mapId()==162,"G2-03 independent Load cannot return162");std::cout<<"G2-03 independent Load/reentry passed\n";return 0;}
 need(mode=="natural"&&run.game.mapId()==151,"G2-03 natural source differs");const auto start=run.game.session().exportState();
 if(!run.game.session().flag(381)||!run.game.session().flag(384)){need(run.game.session().magazine(22)==3,"G2-03 pre-lift source real rockets differ");run.equip(21);run.enterLift();run.fight();need(run.game.session().magazine(22)==3,"G2-03 pre-lift spent conserved rockets");run.equip(22);}else{run.enterLift();}
 run.enterHunters();run.barrel();if(!run.alive().empty()){run.actObject("m162-e6");need(run.game.mapId()==160,"G2-03 safe reload room absent");if(run.game.session().hp()<80&&run.game.session().count(5)>0){run.item(5);}run.enterHunters();run.fight();}
 run.actObject("m162-e13");need(run.game.mapId()==163,"G2-03 natural163 absent");run.actObject("m163-e3");need(run.game.mapId()==162,"G2-03 natural162 return absent");need(run.alive().empty(),"G2-03 same scene death lost");run.back();run.saveMonitor(2,true);need(!std::filesystem::exists(root/"slot-02.json")&&read((root/"slot-01.json").c_str())==source,"G2-03 cancelled save wrote");run.saveMonitor(2);auto final=disk.read(2);need(final.scene.map==151&&final.continuation.kind=="ordinary"&&final.session.saveCount==start.saveCount+1,"G2-03 natural ordinary save wrong");std::cout<<"G2-03 natural ticks="<<run.ticks<<" maps="<<Json(run.maps)<<" hp="<<run.game.session().hp()<<" I22="<<run.game.session().magazine(22)<<" count35="<<run.game.session().variable(35)<<" passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
